function CategoryIcon({
  category,
  className = 'h-6 w-6',
}: {
  category: ToolCategoryId;
  className?: string;
}) {
  return <HealthIcon name={CATEGORY_ICON_BY_ID[category]} className={className} />;
}

function ToolIcon({
  tool,
  categoryId,
  className = 'h-6 w-6',
}: {
  tool: ToolCatalogItem;
  categoryId?: ToolCategoryId;
  className?: string;
}) {
  const iconName = TOOL_ICON_BY_ID[tool.id] ?? CATEGORY_ICON_BY_ID[categoryId ?? tool.category];

  return <HealthIcon name={iconName} className={className} />;
}

function normalizeText(value: string) {
  return value
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function ToolCard({
  tool,
  displayCategoryId,
}: {
  tool: ToolCatalogItem;
  displayCategoryId?: ToolCategoryId;
}) {
  const category = getCategoryById(displayCategoryId ?? tool.category);
  if (!category) return null;

  return (
    <Link
      href={tool.href}
      className="group flex h-full rounded-[1.25rem] border border-white/80 bg-white/92 p-4 shadow-[0_12px_28px_rgba(20,37,45,0.06)] transition duration-200 hover:-translate-y-0.5 hover:border-[#c5dadd] hover:shadow-[0_16px_36px_rgba(20,37,45,0.10)]"
    >
      <div className="flex w-full items-start gap-4">
        <div
          className={`flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl ${category.softAccent} ${category.accent}`}
        >
          <ToolIcon tool={tool} categoryId={displayCategoryId} className="h-7 w-7" />
        </div>

        <div className="min-w-0 flex-1 space-y-3">
          <div className="flex flex-wrap items-start justify-between gap-2">
            <h3 className="text-base font-semibold leading-6 text-slate-950 transition group-hover:text-[#2b5d68]">
              {tool.title}
            </h3>
            {tool.badge ? (
              <span className="rounded-full border border-[#d5e4e7] bg-[#f7fbfc] px-2.5 py-1 text-[11px] font-semibold uppercase tracking-wide text-[#557278]">
                {tool.badge}
              </span>
            ) : null}
          </div>

          <p
            title={tool.summary}
            className="overflow-hidden text-[13px] leading-5 text-[#5b7076] [display:-webkit-box] [-webkit-box-orient:vertical] [-webkit-line-clamp:2]"
          >
            {tool.summary}
          </p>

          <div className="flex flex-wrap gap-2">
            <span
              className={`rounded-full px-2.5 py-1 text-[11px] font-semibold ${category.softAccent} ${category.accent}`}
            >
              {category.label}
            </span>
            {tool.tags.slice(0, 2).map((tag) => (
              <span
                key={tag}
                className="rounded-full border border-[#e0eaec] bg-white px-2.5 py-1 text-[11px] font-medium text-[#6a7f85]"
              >
                {tag}
              </span>
            ))}
          </div>
        </div>
      </div>
    </Link>
  );
}

export default function ToolsExplorer() {
  const [query, setQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState<FilterId>('all');

  const normalizedQuery = normalizeText(query.trim());
  const isFiltering = Boolean(normalizedQuery) || activeFilter !== 'all';
  const matchesQuery = (tool: ToolCatalogItem) =>
    !normalizedQuery || normalizeText(tool.searchText).includes(normalizedQuery);
  const matchesActiveFilter = (tool: ToolCatalogItem) =>
    activeFilter === 'all'
      ? true
      : activeFilter === 'featured'
        ? tool.featured
        : toolBelongsToCategory(tool, activeFilter);

  const queryMatchedTools = TOOLS_CATALOG.filter(matchesQuery);
  const visibleTools = TOOLS_CATALOG.filter((tool) => {
    return matchesQuery(tool) && matchesActiveFilter(tool);
  });

  const categorySections = TOOL_CATEGORIES.map((category) => {
    const items = visibleTools
      .filter((tool) => toolBelongsToCategory(tool, category.id))
      .sort((left, right) => left.title.localeCompare(right.title, 'es'));

    return { category, items };
  }).filter((section) => section.items.length > 0);

  const totalCategories = TOOL_CATEGORIES.length;
  const totalTools = TOOLS_CATALOG.length;
  const queryMatchedFeaturedTools = FEATURED_TOOLS.filter(matchesQuery);
  const visibleFeaturedTools = queryMatchedFeaturedTools.filter(matchesActiveFilter);
  const filterOptions = [
    { id: 'all' as const, label: 'Todas', count: queryMatchedTools.length },
    { id: 'featured' as const, label: 'Destacadas', count: queryMatchedFeaturedTools.length },
    ...TOOL_CATEGORIES.map((category) => ({
      id: category.id,
      label: category.label,
      count: queryMatchedTools.filter((tool) => toolBelongsToCategory(tool, category.id)).length,
    })),
  ];
  const activeFilterLabel =
    activeFilter === 'all'
      ? null
      : activeFilter === 'featured'
        ? 'Destacadas'
        : (getCategoryById(activeFilter)?.label ?? null);

  const clearFilters = () => {
    setQuery('');
    setActiveFilter('all');
  };

  const resultsSection = (
    <section className="space-y-5">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <p className="text-xs font-semibold uppercase tracking-[0.18em] text-[#6a838a]">
            Resultado
          </p>
          <h2 className="mt-1 text-2xl font-semibold text-slate-950">
            {visibleTools.length === totalTools && activeFilter === 'all' && !normalizedQuery
              ? 'Todo el catálogo'
              : 'Herramientas filtradas'}
          </h2>
        </div>
        <p className="text-sm text-[#5d7379]">
          {visibleTools.length} resultado{visibleTools.length === 1 ? '' : 's'}
        </p>
      </div>

      {categorySections.length > 0 ? (
        categorySections.map(({ category, items }) => (
          <section
            key={category.id}
            className="overflow-hidden rounded-[1.75rem] border border-[#dbe8eb] bg-[linear-gradient(180deg,rgba(255,255,255,0.96),rgba(248,251,252,0.96))] shadow-[0_12px_28px_rgba(20,37,45,0.05)]"
          >
            <div
              className={`flex flex-col gap-3 border-b border-white/70 px-4 py-3 shadow-[inset_0_1px_0_rgba(255,255,255,0.35)] sm:flex-row sm:items-center sm:justify-between sm:px-5 ${category.softAccent}`}
            >
              <div className="flex items-center gap-4">
                <div
                  className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-white/85 bg-white/80 shadow-[0_6px_16px_rgba(20,37,45,0.08)] ${category.accent}`}
                >
                  <CategoryIcon category={category.id} className="h-6 w-6 sm:h-7 sm:w-7" />
                </div>
                <div>
                  <h3 className={`text-lg font-semibold ${category.accent}`}>{category.label}</h3>
                </div>
              </div>
              <span className="w-fit rounded-full border border-white/85 bg-white/85 px-3 py-1 text-xs font-semibold text-[#425f66] shadow-[0_4px_12px_rgba(20,37,45,0.05)]">
                {items.length} herramienta{items.length === 1 ? '' : 's'}
              </span>
            </div>

            <div className="p-4 sm:p-5">
              <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
              {items.map((tool) => (
                <ToolCard
                  key={`${category.id}-${tool.id}`}
                  tool={tool}
                  displayCategoryId={category.id}
                />
              ))}
              </div>
            </div>
          </section>
        ))
      ) : (
        <div className="rounded-[1.75rem] border border-dashed border-[#cbdde1] bg-[linear-gradient(180deg,#ffffff,#f9fcfd)] px-6 py-10 text-center shadow-[0_10px_24px_rgba(20,37,45,0.04)]">
          <h3 className="text-lg font-semibold text-slate-950">Sin coincidencias</h3>
          <p className="mt-2 text-sm leading-6 text-[#61767c]">
            Ajusta la búsqueda o cambia el filtro para volver a mostrar herramientas.
          </p>
          <button
            type="button"
            onClick={clearFilters}
            className="mt-5 inline-flex rounded-full border border-[#cfe0e4] bg-white px-4 py-2 text-sm font-semibold text-[#2b5d68] transition hover:border-[#bcd2d8] hover:bg-[#f5fafb]"
          >
            Limpiar filtros
          </button>
        </div>
      )}
    </section>
  );

  const discoverySection = (
    <section className="space-y-4">
      <div className="rounded-[1.45rem] border border-[#dbe8eb] bg-[linear-gradient(180deg,#ffffff,#f7fbfc)] p-4 shadow-[0_12px_28px_rgba(20,37,45,0.05)]">
        <div className="flex flex-wrap items-end justify-between gap-3">
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.18em] text-[#6a838a]">
              Selección destacada
            </p>
          </div>
          <p className="text-xs text-[#5d7379] sm:text-sm">
            {visibleFeaturedTools.length} visibles
          </p>
        </div>

        <div className="mt-3 grid gap-2 md:grid-cols-2 xl:grid-cols-3">
          {visibleFeaturedTools.length > 0 ? (
            visibleFeaturedTools.map((tool) => {
              const category = getCategoryById(tool.category);
              if (!category) return null;

              return (
                <Link
                  key={tool.id}
                  href={tool.href}
                  className="group flex items-center gap-2.5 rounded-[1rem] border border-[#e4edef] bg-white/92 px-3 py-2.5 transition hover:border-[#cadce1] hover:bg-white"
                >
                  <div
                    className={`flex h-11 w-11 shrink-0 items-center justify-center rounded-xl ${category.softAccent} ${category.accent}`}
                  >
                    <ToolIcon tool={tool} className="h-6 w-6" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <h3 className="truncate text-sm font-semibold leading-5 text-slate-950 transition group-hover:text-[#2b5d68]">
                        {tool.title}
                      </h3>
                      {tool.badge ? (
                        <span className="rounded-full bg-[#edf5f7] px-2 py-0.5 text-[11px] font-semibold text-[#5f7880]">
                          {tool.badge}
                        </span>
                      ) : null}
                    </div>
                    <p className="text-[11px] font-medium text-[#61767c]">{category.label}</p>
                  </div>
                  <span className="text-[#7a9399]">
                    <ArrowIcon />
                  </span>
                </Link>
              );
            })
          ) : (
            <div className="rounded-[1.2rem] border border-dashed border-[#cfe0e4] bg-white/75 px-4 py-5 text-sm text-[#61767c] md:col-span-2 xl:col-span-3">
              No hay destacadas que coincidan con la búsqueda actual.
            </div>
          )}
        </div>
      </div>
    </section>
  );

  return (
    <div className="space-y-8">
      <section className="relative overflow-hidden rounded-[2rem] border border-white/60 bg-[linear-gradient(135deg,rgba(232,244,246,0.98),rgba(255,255,255,0.88))] px-6 py-6 shadow-[0_18px_48px_rgba(20,37,45,0.10)] sm:px-8 sm:py-7">
        <div className="absolute inset-0 overflow-hidden">
          <div
            className="absolute inset-0 bg-cover bg-center opacity-[0.12]"
            style={{ backgroundImage: 'url(/urg-background.png)' }}
          />
          <div className="absolute -left-10 top-0 h-32 w-32 rounded-full bg-[#cfe2e6]/65 blur-3xl" />
          <div className="absolute right-0 top-10 h-40 w-40 rounded-full bg-[#dce9f3]/70 blur-3xl" />
          <div className="absolute bottom-0 left-1/3 h-32 w-32 rounded-full bg-[#d9efe8]/70 blur-3xl" />
        </div>

        <div className="relative z-10 space-y-4">
          <div className="inline-flex items-center gap-2 rounded-full border border-white/70 bg-white/70 px-3 py-1 text-xs font-semibold uppercase tracking-[0.2em] text-[#2b5d68] backdrop-blur">
            Herramientas clínicas
          </div>

          <div className="space-y-3">
            <div className="max-w-3xl space-y-2">
              <h1 className="text-3xl font-semibold tracking-tight text-slate-950 sm:text-4xl">
                Herramientas
              </h1>
              <p className="max-w-2xl text-xs leading-5 text-[#5a747a] sm:text-sm">
                Busca por nombre o filtra por área para ir directo a la herramienta que necesitas.
              </p>
            </div>

            <label className="block max-w-3xl">
              <span className="sr-only">Buscar herramienta</span>
              <span className="flex items-center gap-3 rounded-[1.2rem] border border-white/70 bg-white/80 px-4 py-3 text-[#6a7f85] shadow-[0_12px_30px_rgba(20,37,45,0.08)] backdrop-blur-sm">
                <SearchIcon />
                <input
                  type="search"
                  value={query}
                  onChange={(event) => setQuery(event.target.value)}
                  placeholder="Buscar por nombre, utilidad o etiqueta"
                  className="w-full bg-transparent text-sm text-slate-900 outline-none placeholder:text-[#8aa0a6]"
                />
              </span>
            </label>

            <div className="flex flex-wrap gap-2 text-xs text-[#587077] sm:text-sm">
              <span className="rounded-full border border-white/80 bg-white/75 px-3 py-1 backdrop-blur-sm">
                {totalTools} herramientas
              </span>
              <span className="rounded-full border border-white/80 bg-white/75 px-3 py-1 backdrop-blur-sm">
                {totalCategories} áreas clínicas
              </span>
              <span className="rounded-full border border-white/80 bg-white/75 px-3 py-1 backdrop-blur-sm">
                {FEATURED_TOOLS.length} accesos directos
              </span>
            </div>
          </div>
        </div>
      </section>

      <section className="space-y-4">
        <div className="flex flex-wrap gap-2">
          {filterOptions.map((filter) => {
            const active = activeFilter === filter.id;
            const hasResults = filter.count > 0;

            return (
              <button
                key={filter.id}
                type="button"
                onClick={() => setActiveFilter(filter.id)}
                className={`inline-flex items-center gap-2 rounded-full border px-4 py-2 text-sm font-medium transition ${
                  active
                    ? 'border-[#2b5d68] bg-[#2b5d68] text-white shadow-[0_10px_24px_rgba(43,93,104,0.18)]'
                    : isFiltering
                      ? hasResults
                        ? 'border-[#c7dbe0] bg-[#f5fafb] text-[#355962] shadow-[0_6px_18px_rgba(20,37,45,0.05)] hover:border-[#a9c8cf] hover:bg-white'
                        : 'border-[#e5ecee] bg-white/75 text-[#9aaeb3] opacity-60 hover:border-[#d8e4e7] hover:bg-white/90'
                      : 'border-[#d7e5e8] bg-white text-[#49646b] hover:border-[#b8d0d6] hover:bg-[#f5fafb]'
                }`}
              >
                <span>{filter.label}</span>
                <span
                  className={`rounded-full px-2 py-0.5 text-xs ${
                    active
                      ? 'bg-white/18 text-white'
                      : isFiltering
                        ? hasResults
                          ? 'bg-[#dcecf0] text-[#355962]'
                          : 'bg-[#eff4f5] text-[#8ca1a6]'
                        : 'bg-[#edf5f7] text-[#557278]'
                  }`}
                >
                  {filter.count}
                </span>
              </button>
            );
          })}
        </div>

        {isFiltering ? (
          <div className="rounded-[1.5rem] border border-[#cfe0e4] bg-[linear-gradient(180deg,#ffffff,#f7fbfc)] p-4 shadow-[0_10px_24px_rgba(20,37,45,0.05)]">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <div className="space-y-1">
                <p className="text-xs font-semibold uppercase tracking-[0.18em] text-[#6a838a]">
                  Filtro activo
                </p>
                <p className="text-sm text-[#4f696f]">
                  Mostrando{' '}
                  <span className="font-semibold text-slate-950">
                    {visibleTools.length} resultado{visibleTools.length === 1 ? '' : 's'}
                  </span>
                  {normalizedQuery ? (
                    <>
                      {' '}
                      para <span className="font-semibold text-slate-950">“{query.trim()}”</span>
                    </>
                  ) : null}
                  {activeFilterLabel ? (
                    <>
                      {' '}
                      en <span className="font-semibold text-slate-950">{activeFilterLabel}</span>
                    </>
                  ) : null}
                  .
                </p>
              </div>
              <button
                type="button"
                onClick={clearFilters}
                className="inline-flex rounded-full border border-[#cfe0e4] bg-white px-4 py-2 text-sm font-semibold text-[#2b5d68] transition hover:border-[#bcd2d8] hover:bg-[#f5fafb]"
              >
                Limpiar filtros
              </button>
            </div>
          </div>
        ) : null}
      </section>

      {isFiltering ? resultsSection : null}
      {isFiltering ? null : discoverySection}
      {isFiltering ? null : resultsSection}
    </div>
  );
}
